steps.action:
curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { projects(filter: { name: { contains: \"Checkout Redesign\" } }) { nodes { id name description state leader { id name } } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { projects(filter: { name: { contains: \"Checkout Redesign\" } }) { nodes { id name description state lead { id name } } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { projects { nodes { id name description lead { id name } } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { teams { nodes { id name key } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { projects(first: 100) { nodes { id name description lead { id name } } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { projects(teamId: \"t-web\", first: 100) { nodes { id name description lead { id name } } } }"
  }'

curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { __type(name: \"Query\") { fields { name args { name type { name kind ofType { name kind } } } } } }"
  }' | python3 -m json.tool 2>/dev/null || curl -s -X POST https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { __type(name: \"Query\") { fields { name } } }"
  }'

